class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        mentions = [0] * numberOfUsers
        offline_until = [0] * numberOfUsers  # timestamp until which user is offline

        # Sort events by timestamp; ensure OFFLINE comes before MESSAGE at same timestamp
        events.sort(key=lambda e: (int(e[1]), 0 if e[0] == "OFFLINE" else 1))

        for event in events:
            typ, ts, data = event[0], int(event[1]), event[2]
            if typ == "OFFLINE":
                uid = int(data)
                offline_until[uid] = ts + 60
            else:  # MESSAGE
                if data == "ALL":
                    for i in range(numberOfUsers):
                        mentions[i] += 1
                elif data == "HERE":
                    for i in range(numberOfUsers):
                        if offline_until[i] <= ts:
                            mentions[i] += 1
                else:
                    for token in data.split():
                        uid = int(token[2:])
                        mentions[uid] += 1

        return mentions
