class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        n = len(nums)
        prefix = [0] * (n + 1)
        for i in range(n):
            prefix[i + 1] = prefix[i] + nums[i]

        # dp[i][j] = max sum using j subarrays from first i elements
        dp = [[-10**18] * (k + 1) for _ in range(n + 1)]
        dp[0][0] = 0

        for i in range(1, n + 1):
            dp[i][0] = 0
            for j in range(1, min(k, i // m) + 1):
                # Option 1: don't use element i-1 in any subarray
                dp[i][j] = dp[i - 1][j]

                # Option 2: end a subarray at i-1, starting at some p where length >= m
                # sum of subarray = prefix[i] - prefix[p]
                for p in range(0, i - m + 1):
                    if dp[p][j - 1] != -10**18:
                        dp[i][j] = max(dp[i][j], dp[p][j - 1] + prefix[i] - prefix[p])

        return dp[n][k]
