import sys

def solve():
    data = sys.stdin.read().strip().split()
    N = int(data[0])
    P = int(data[1])
    maxM = N * (N - 1) // 2

    # binomial coefficients modulo P
    C = [[0] * (N + 1) for _ in range(N + 1)]
    for i in range(N + 1):
        C[i][0] = C[i][i] = 1
        for j in range(1, i):
            C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % P

    pow2 = [1] * (maxM + 1)
    for i in range(1, maxM + 1):
        pow2[i] = (pow2[i - 1] * 2) % P

    # dp[(v, even_cnt, prev_size, parity)] = list of coeffs length maxM+1
    dp = {}
    dp[(1, 1, 1, 0)] = [1] + [0] * maxM

    for v in range(1, N):
        # get keys with current v
        keys = [k for k in dp if k[0] == v]
        for key in keys:
            poly = dp[key]
            if not any(poly):
                continue
            v_cur, even_cnt, prev_size, layer_parity = key
            for s in range(1, N - v_cur + 1):
                # inter-layer edges polynomial
                poly_inter = [0] * (maxM + 1)
                for i in range(s + 1):
                    edges_cnt = prev_size * (s - i)
                    if edges_cnt > maxM:
                        continue
                    ways = (C[s][i] * pow2[edges_cnt]) % P
                    if i & 1:
                        ways = (-ways) % P
                    poly_inter[edges_cnt] = (poly_inter[edges_cnt] + ways) % P

                intra_edges = s * (s - 1) // 2
                intra_ways = pow2[intra_edges]

                poly_step = [0] * (maxM + 1)
                for e1 in range(maxM + 1):
                    if poly_inter[e1] == 0:
                        continue
                    e2 = e1 + intra_edges
                    if e2 > maxM:
                        continue
                    poly_step[e2] = (poly_step[e2] + poly_inter[e1] * intra_ways) % P

                new_poly = [0] * (maxM + 1)
                for e_old in range(maxM + 1):
                    if poly[e_old] == 0:
                        continue
                    pe = poly[e_old]
                    for e_add in range(maxM + 1 - e_old):
                        if poly_step[e_add]:
                            new_poly[e_old + e_add] = (new_poly[e_old + e_add] + pe * poly_step[e_add]) % P

                new_v = v_cur + s
                new_even = even_cnt + (s if layer_parity == 1 else 0)
                new_prev_size = s
                new_layer_parity = 1 - layer_parity
                new_key = (new_v, new_even, new_prev_size, new_layer_parity)
                if new_key not in dp:
                    dp[new_key] = [0] * (maxM + 1)
                dest = dp[new_key]
                for e in range(maxM + 1):
                    if new_poly[e]:
                        dest[e] = (dest[e] + new_poly[e]) % P

    ans = [0] * (maxM + 1)
    for key, poly in dp.items():
        v, even_cnt, _, _ = key
        if v == N and even_cnt == N // 2:
            for e in range(maxM + 1):
                ans[e] = (ans[e] + poly[e]) % P

    out = []
    for M in range(N - 1, maxM + 1):
        out.append(str(ans[M] % P))
    print(" ".join(out))

if __name__ == "__main__":
    solve()
