from typing import List

class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)

        def can(x: int) -> bool:
            need = [(x + p - 1) // p for p in points]
            visited = [0] * n
            moves = 0
            for i in range(n):
                moves += 1
                if moves > m:
                    return False
                visited[i] += 1
                if visited[i] < need[i]:
                    diff = need[i] - visited[i]
                    moves += 2 * diff
                    if moves > m:
                        return False
                    if i + 1 < n:
                        visited[i + 1] += diff
            return True

        lo, hi = 0, max(points) * (m // 2 + 2)
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if can(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo
