from typing import List

class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)

        def can(x: int) -> bool:
            need = [(x + p - 1) // p for p in points]
            moves = 0
            carry = 0  # visits already accumulated for the next index from previous bounces
            for i in range(n):
                # move to i
                moves += 1
                if moves > m:
                    return False
                visits = 1 + carry  # arrival + carried from previous bounces
                if visits < need[i]:
                    diff = need[i] - visits
                    moves += 2 * diff
                    if moves > m:
                        return False
                    carry = diff
                else:
                    carry = 0
                # handle last index case: if still short, need bounce back
                if i == n - 1 and visits < need[i]:
                    diff = need[i] - visits
                    moves += 2 * diff
                    if moves > m:
                        return False
            return True

        lo, hi = 0, max(points) * (m // 2 + 2)
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if can(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo
