class Solution:
    def minCostGoodCaption(self, caption: str) -> str:
        n = len(caption)
        if n < 3:
            return ""

        # Try DP with minCost and best string
        INF = 10**9
        # dp[i] = min cost from i to end
        dp = [INF]*(n+1)
        dp[n] = 0

        # We'll also store the best string for each i
        best_str = [None]*(n+1)
        best_str[n] = ""

        # We can compute dp backwards
        for i in range(n-1, -1, -1):
            for length in range(3, n-i+1):
                j = i + length
                if dp[j] >= INF:
                    continue
                # cost for block i..j-1 with all same letter
                # min over letter c
                min_block_cost = INF
                best_letter = None
                for c in range(26):
                    cost_sum = 0
                    for k in range(i, j):
                        cost_sum += abs(ord(caption[k]) - ord('a') - c)
                    if cost_sum < min_block_cost:
                        min_block_cost = cost_sum
                        best_letter = c
                    elif cost_sum == min_block_cost:
                        # tie: smaller letter better for lexicographic
                        if c < best_letter:
                            best_letter = c

                total = min_block_cost + dp[j]
                if total < dp[i]:
                    dp[i] = total
                    best_str[i] = chr(ord('a')+best_letter)*length + best_str[j]
                elif total == dp[i]:
                    cand = chr(ord('a')+best_letter)*length + best_str[j]
                    if cand < best_str[i]:
                        best_str[i] = cand

        if dp[0] >= INF:
            return ""
        return best_str[0]
