from typing import List

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        # directions: 0:SE(1,1),1:SW(1,-1),2:NW(-1,-1),3:NE(-1,1)
        dirs = [(1,1),(1,-1),(-1,-1),(-1,1)]

        # dp[r][c][d][s]: length starting at (r,c), dir d, logic state s
        # s: 0 -> expect 1(only for start), 1-> expect 2, 2-> expect 0
        dp = [[[[0]*3 for _ in range(4)] for _ in range(m)] for _ in range(n)]

        expect = [1,2,0]
        next_state = [1,2,1]

        # fill dp backwards
        for r in range(n-1,-1,-1):
            for c in range(m-1,-1,-1):
                for d in range(4):
                    dr, dc = dirs[d]
                    for s in range(3):
                        if grid[r][c] == expect[s]:
                            nr, nc = r+dr, c+dc
                            if 0 <= nr < n and 0 <= nc < m:
                                dp[r][c][d][s] = 1 + dp[nr][nc][d][next_state[s]]
                            else:
                                dp[r][c][d][s] = 1

        ans = 0
        for r in range(n):
            for c in range(m):
                if grid[r][c] == 1:
                    for d in range(4):
                        # straight without turn:
                        straight = dp[r][c][d][0]
                        ans = max(ans, straight)

                        # try turning after m steps in dir d
                        dr0, dc0 = dirs[d]
                        d1 = (d+1)%4
                        dr1, dc1 = dirs[d1]
                        for m in range(straight):
                            # last cell in first segment is at m steps from start
                            r2 = r + m*dr0
                            c2 = c + m*dc0
                            # next step index = m+1 in the overall sequence
                            total_first = m+1
                            step_index = m+1
                            if step_index == 0:
                                nxt_s = 1
                            elif step_index % 2 == 1:
                                nxt_s = 1  # expect 2
                            else:
                                nxt_s = 2  # expect 0

                            nr, nc = r2+dr1, c2+dc1
                            if 0 <= nr < n and 0 <= nc < m:
                                total_len = total_first + dp[nr][nc][d1][nxt_s]
                            else:
                                total_len = total_first
                            ans = max(ans, total_len)

        return ans
