from typing import List

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        # Directions: 0:SE(1,1), 1:SW(1,-1), 2:NW(-1,-1), 3:NE(-1,1)
        dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]

        # Clockwise turn order: SE->SW->NW->NE->SE
        # So clockwise next: 0->1, 1->2, 2->3, 3->0
        def cw(d):
            return (d + 1) % 4

        # The sequence values based on step index k (0-based):
        # k=0 -> 1, k>=1: odd->2, even->0
        def expected_value(k):
            if k == 0:
                return 1
            elif k % 2 == 1:
                return 2
            else:
                return 0

        # Precompute straight continuation lengths for each (r, c, d) with each starting "phase".
        # Phase p represents the value we expect at the current cell:
        # The pattern starting at step index where step%2 -> value mapping:
        # For k>=1: k odd => 2, k even => 0
        # We'll represent expectations as:
        #   phase 0: expect 1 (only when k=0)
        #   phase 1: expect 2 (when k odd)
        #   phase 2: expect 0 (when k even, k>=2)
        expect = [1, 2, 0]
        next_phase = [1, 2, 1]  # 0->1, 1->2, 2->1

        dp = [[[[0]*3 for _ in range(4)] for _ in range(m)] for _ in range(n)]

        for r in range(n-1, -1, -1):
            for c in range(m-1, -1, -1):
                for d in range(4):
                    dr, dc = dirs[d]
                    for ph in range(3):
                        if grid[r][c] == expect[ph]:
                            nr, nc = r+dr, c+dc
                            if 0 <= nr < n and 0 <= nc < m:
                                dp[r][c][d][ph] = 1 + dp[nr][nc][d][next_phase[ph]]
                            else:
                                dp[r][c][d][ph] = 1
                        else:
                            dp[r][c][d][ph] = 0

        ans = 0
        for r in range(n):
            for c in range(m):
                if grid[r][c] != 1:
                    continue
                # Start must be 1, so initial phase=0
                for d in range(4):
                    straight_len = dp[r][c][d][0]
                    ans = max(ans, straight_len)

                    dr0, dc0 = dirs[d]
                    d1 = cw(d)
                    dr1, dc1 = dirs[d1]

                    # Try turning after m steps in dir d
                    # m goes from 0 to straight_len-1
                    # The cell at step m in first segment is (r2, c2)
                    # Then next step is m+1 in new direction
                    for m in range(straight_len):
                        r2 = r + m*dr0
                        c2 = c + m*dc0
                        first_half_len = m + 1

                        # After placing step m (value at index m),
                        # next step index = m+1
                        k_next = m + 1
                        if k_next == 0:
                            ph1 = 1
                        elif k_next % 2 == 1:
                            ph1 = 1  # expect 2
                        else:
                            ph1 = 2  # expect 0

                        nr, nc = r2 + dr1, c2 + dc1
                        if 0 <= nr < n and 0 <= nc < m:
                            total = first_half_len + dp[nr][nc][d1][ph1]
                        else:
                            total = first_half_len
                        ans = max(ans, total)

        return ans
