    it = iter(data)
    T = next(it)
    out = []

    for _ in range(T):
        N = next(it)
        M = 2 * N
        A = [next(it) for _ in range(M)]

        first = [-1] * (N + 1)
        bad = [False] * (N + 1)

        for i, x in enumerate(A):
            if first[x] == -1:
                first[x] = i
            else:
                if i == first[x] + 1:
                    bad[x] = True

        B = N + 1
        d = {}

        for i in range(M - 1):
            x = A[i]
            y = A[i + 1]
            if x == y:
                continue

            if x < y:
                key = x * B + y
            else:
                key = y * B + x

            if key in d:
                mn, mx = d[key]
                if i < mn:
                    mn = i
                if i > mx:
                    mx = i
                d[key] = (mn, mx)
            else:
                d[key] = (i, i)

        ans = 0
        for key, (mn, mx) in d.items():
            if mx - mn >= 2:
                small = key // B
                large = key % B
                if not bad[small] and not bad[large]:
                    ans += 1

        out.append(str(ans))

    sys.stdout.write("\n".join(out))

