class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)
        if n == 1:
            return 1

        # prev1 stores DP values for length 1
        prev1 = [[1] * (k + 1) for _ in range(n)]
        prev2 = None

        for length in range(2, n + 1):
            m = n - length + 1
            curr = [[0] * (k + 1) for _ in range(m)]

            for i in range(m):
                j = i + length - 1
                d = abs(ord(s[i]) - ord(s[j]))
                if d > 13:
                    d = 26 - d

                for c in range(k + 1):
                    best = max(prev1[i][c], prev1[i + 1][c])

                    if c >= d:
                        if prev2 is None:
                            best = max(best, 2)
                        else:
                            best = max(best, prev2[i + 1][c - d] + 2)

                    curr[i][c] = best

            prev2, prev1 = prev1, curr

        return prev1[0][k]
