                offline_until[user_id] = t + 60
            else:
                content = event[2]

                if content == "ALL":
                    for i in range(numberOfUsers):
                        mentions[i] += 1
                elif content == "HERE":
                    for i in range(numberOfUsers):
                        if offline_until[i] <= t:
                            mentions[i] += 1
