        n = len(nums)
        pref = [0] * (n + 1)
        for i, x in enumerate(nums, 1):
            pref[i] = pref[i - 1] + x

        NEG = -10**18
        dp = [[NEG] * (n + 1) for _ in range(k + 1)]

        for i in range(n + 1):
            dp[0][i] = 0

        for j in range(1, k + 1):
            best = NEG
            for i in range(1, n + 1):
                if i >= m:
                    t = i - m
                    best = max(best, dp[j - 1][t] - pref[t])

                dp[j][i] = dp[j][i - 1]
                if best != NEG:
                    dp[j][i] = max(dp[j][i], pref[i] + best)

        return dp[k][n]
