class Solution:
    def maxDistance(self, s: str, k: int) -> int:
        directions = {
            'N': (0, 1),
            'S': (0, -1),
            'E': (1, 0),
            'W': (-1, 0)
        }
        signs = [(1, 1), (1, -1), (-1, 1), (-1, -1)]
        stats = [[0, 0] for _ in range(4)]
        ans = 0

        for ch in s:
            dx, dy = directions[ch]
            for i, (sx, sy) in enumerate(signs):
                contribution = sx * dx + sy * dy
                if contribution == 1:
                    stats[i][0] += 1
                else:
                    stats[i][0] -= 1
                    stats[i][1] += 1

                base, negatives = stats[i]
                current = base + 2 * min(k, negatives)
                ans = max(ans, current)

        return ans
