from typing import List

class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        children = [{}]
        cnt = [0]
        depth = [0]
        paths = []
        max_depth = 0

        for w in words:
            node = 0
            path = []
            d = 0
            for ch in w:
                d += 1
                nxt = children[node].get(ch)
                if nxt is None:
                    nxt = len(children)
                    children[node][ch] = nxt
                    children.append({})
                    cnt.append(0)
                    depth.append(d)
                node = nxt
                cnt[node] += 1
                path.append(node)
            paths.append(path)
            if d > max_depth:
                max_depth = d

        active = [0] * (max_depth + 1)
        for node in range(1, len(cnt)):
            if cnt[node] >= k:
                active[depth[node]] += 1

        size = 1
        while size < max_depth + 1:
            size <<= 1

        tree = [0] * (2 * size)
        for d in range(1, max_depth + 1):
            tree[size + d] = active[d]

        for p in range(size - 1, 0, -1):
            tree[p] = tree[p << 1] + tree[(p << 1) | 1]

        def update(d: int, delta: int) -> None:
            p = size + d
            tree[p] += delta
            p >>= 1
            while p:
                tree[p] = tree[p << 1] + tree[(p << 1) | 1]
                p >>= 1

        def rightmost() -> int:
            if tree[1] == 0:
                return 0
            p = 1
            while p < size:
                if tree[(p << 1) | 1] > 0:
                    p = (p << 1) | 1
                else:
                    p = p << 1
            d = p - size
            return d if d <= max_depth else 0

        ans = []
        for path in paths:
            for node in path:
                if cnt[node] == k:
                    update(depth[node], -1)
                cnt[node] -= 1

            ans.append(rightmost())

            for node in path:
                if cnt[node] == k - 1:
                    update(depth[node], 1)
                cnt[node] += 1

        return ans
