from typing import List
from collections import deque

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        # Reverse the graph: original u -> v becomes v -> u.
        rev = [[] for _ in range(n)]
        max_w = 0
        for u, v, w in edges:
            rev[v].append((u, w))
            if w > max_w:
                max_w = w

        def can_reach_all(limit: int) -> bool:
            seen = [False] * n
            seen[0] = True
            q = deque([0])
            cnt = 1

            while q:
                u = q.popleft()
                for v, w in rev[u]:
                    if w <= limit and not seen[v]:
                        seen[v] = True
                        cnt += 1
                        q.append(v)

            return cnt == n

        # If even using all edges we cannot make every node reach 0, impossible.
        if not can_reach_all(max_w):
            return -1

        weights = sorted({w for _, _, w in edges})
        lo, hi = 0, len(weights) - 1
        ans = max_w

        while lo <= hi:
            mid = (lo + hi) // 2
            if can_reach_all(weights[mid]):
                ans = weights[mid]
                hi = mid - 1
            else:
                lo = mid + 1

        return ans
