        def prefix(n: int) -> int:
            if n <= 0:
                return 0
            total = 0
            start = 1
            k = 1
            while start <= n:
                end = min(n, start * 4 - 1)
                total += (end - start + 1) * k
                start *= 4
                k += 1
            return total

        def depth(x: int) -> int:
