            p = 4
            while x >= p:
                k += 1
                p *= 4
            return k

        ans = 0
        for l, r in queries:
            total_ops = prefix(r) - prefix(l - 1)
            max_ops = depth(r)
            ans += max(max_ops, (total_ops + 1) // 2)

        return ans
