import sys

def solve() -> None:
    data = sys.stdin.read().split()
    if not data:
        return
    N = int(data[0])
    MOD = int(data[1])

    half = N // 2
    maxE = N * (N - 1) // 2
    N1 = N + 1

    fact = [1] * (N + 1)
    for i in range(1, N + 1):
        fact[i] = fact[i - 1] * i % MOD

    invfact = [1] * (N + 1)
    invfact[N] = pow(fact[N], MOD - 2, MOD)
    for i in range(N, 0, -1):
        invfact[i - 1] = invfact[i] * i % MOD

    def comb_small(n, k):
        if k < 0 or k > n:
            return 0
        return fact[n] * invfact[k] % MOD * invfact[n - k] % MOD

    # trans[a][b] = list of (edge_exponent_shift, coefficient)
    trans = [[None] * (N + 1) for _ in range(N + 1)]
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            w = b * (b - 1) // 2
            lst = []
            for j in range(b + 1):
                coeff = comb_small(b, j)
                if (b - j) & 1:
                    coeff = (-coeff) % MOD
                coeff = coeff * invfact[b] % MOD
                shift = w + a * j
                lst.append((shift, coeff))
            trans[a][b] = lst

    maxlen = [i * (i - 1) // 2 + 1 for i in range(N + 1)]

    # dp[u][((e*2 + p)*N1 + a)]
    dp = [[None] * ((half + 1) * 2 * N1) for _ in range(N + 1)]

    def idx(e, p, a):
        return (e * 2 + p) * N1 + a

    dp[1][idx(1, 0, 1)] = [1]

    BIG = 1 << 63

    for u in range(1, N + 1):
        e_min = max(0, u - half)
        e_max = min(half, u)

        for e in range(e_min, e_max + 1):
            for p in (0, 1):
                base_ep = (e * 2 + p) * N1
                for a in range(1, u + 1):
                    poly = dp[u][base_ep + a]
                    if poly is None:
                        continue

                    for i, val in enumerate(poly):
                        if val >= MOD:
                            poly[i] = val % MOD

                    rem = N - u
                    for b in range(1, rem + 1):
                        newe = e + (b if p == 1 else 0)
                        if newe > half:
                            continue

                        newu = u + b
                        if newu - newe > half:
                            continue

                        newp = 1 - p
                        tid = (newe * 2 + newp) * N1 + b
                        target = dp[newu][tid]
                        if target is None:
                            target = [0] * maxlen[newu]
                            dp[newu][tid] = target

                        for shift, coeff in trans[a][b]:
                            if coeff == 0:
                                continue
                            for i, val in enumerate(poly):
                                if val:
                                    j = i + shift
                                    x = target[j] + val * coeff
                                    if x >= BIG:
                                        x %= MOD
                                    target[j] = x

    total = [0] * (maxE + 1)
    for p in (0, 1):
        for a in range(1, N + 1):
            poly = dp[N][idx(half, p, a)]
            if poly is None:
                continue
            for i, val in enumerate(poly):
                total[i] += val

    for i in range(maxE + 1):
        total[i] %= MOD

    # combinations C(E, M) for E, M <= maxE
    comb = [[0] * (maxE + 1) for _ in range(maxE + 1)]
    for n in range(maxE + 1):
        comb[n][0] = comb[n][n] = 1
        for k in range(1, n):
            comb[n][k] = (comb[n - 1][k - 1] + comb[n - 1][k]) % MOD

    ans = []
    root_factor = fact[N - 1]

    for M in range(N - 1, maxE + 1):
        s = 0
        for E in range(M, maxE + 1):
            if total[E]:
                s = (s + total[E] * comb[E][M]) % MOD
        ans.append(str(s * root_factor % MOD))

    print(" ".join(ans))


if __name__ == "__main__":
    solve()
```

