class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        m = len(conflictingPairs)
        by_y = [[] for _ in range(n + 1)]
        xs = [0] * m

        for i, (a, b) in enumerate(conflictingPairs):
            if a < b:
                x, y = a, b
            else:
                x, y = b, a
            xs[i] = x
            by_y[y].append(i)

        cnt = [0] * (n + 1)
        rep = [-1] * (n + 1)
        gain = [0] * m

        L1 = L2 = 0
        sum_m = 0

        for R in range(1, n + 1):
            for i in by_y[R]:
                v = xs[i]
                if cnt[v] == 0:
                    if v > L1:
                        L2 = L1
                        L1 = v
                    elif v > L2:
                        L2 = v
                    rep[v] = i
                cnt[v] += 1

            sum_m += L1

            if L1 > 0 and cnt[L1] == 1:
                d = L1 - L2
                if d > 0:
                    gain[rep[L1]] += d

        total = n * (n + 1) // 2 - sum_m
        return total + max(gain)
