class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        by_end = [[] for _ in range(n + 1)]
        m = len(conflictingPairs)

        for idx, (a, b) in enumerate(conflictingPairs):
            if a < b:
                x, y = a, b
            else:
                x, y = b, a
            by_end[y].append((x, idx))

        top1_val = 0
        top1_id = -1
        top2_val = 0
        top2_id = -1

        base = 0
        gain = [0] * m

        for r in range(1, n + 1):
            for x, idx in by_end[r]:
                if x > top1_val:
                    top2_val, top2_id = top1_val, top1_id
                    top1_val, top1_id = x, idx
                elif x > top2_val:
                    top2_val, top2_id = x, idx

            if top1_id != -1:
                base += r - top1_val
                gain[top1_id] += top1_val - top2_val
            else:
                base += r

        return base + (max(gain) if gain else 0)
