from array import array

class Solution:
    def minCostGoodCaption(self, caption: str) -> str:
        n = len(caption)
        if n < 3:
            return ""

        INF = 10**9
        M = 78  # 26 chars * 3 lengths

        # dp[i][c][l], l = 1,2,3. l=3 means current run length is at least 3.
        dp = array('i', [INF]) * ((n + 1) * M)

        base = n * M
        for c in range(26):
            dp[base + c * 3 + 2] = 0  # valid finished run

        for i in range(n - 1, -1, -1):
            cur = i * M
            nxt = (i + 1) * M
            ci = ord(caption[i]) - 97

            # Length 1 -> 2, Length 2 -> 3
            for c in range(26):
                off = c * 3
                diff = ci - c
                if diff < 0:
                    diff = -diff
                dp[cur + off] = diff + dp[nxt + off + 1]
                dp[cur + off + 1] = diff + dp[nxt + off + 2]

            # For length >= 3, either continue same char or change to another char.
            best1 = INF
            best2 = INF
            best_idx = -1
            cnt = 0

            for d in range(26):
                diff = ci - d
                if diff < 0:
                    diff = -diff
                val = diff + dp[nxt + d * 3]  # start new run, length 1
                if val < best1:
                    best2 = best1
                    best1 = val
                    best_idx = d
                    cnt = 1
                elif val == best1:
                    cnt += 1
                elif val < best2:
                    best2 = val

            for c in range(26):
                off = c * 3
                diff = ci - c
                if diff < 0:
                    diff = -diff

                cont = diff + dp[nxt + off + 2]
                if c != best_idx:
                    change = best1
                else:
                    change = best1 if cnt > 1 else best2

                dp[cur + off + 2] = cont if cont < change else change

        # Initial state: before first char, choose any char and start length 1.
        ci = ord(caption[0]) - 97
        total = INF
        for c in range(26):
            diff = ci - c
            if diff < 0:
                diff = -diff
            val = diff + dp[M + c * 3]
            if val < total:
                total = val

        if total >= INF:
            return ""

        res = []
        remaining = total
        prev_c = -1
        prev_l = 0

        for i in range(n):
            ci = ord(caption[i]) - 97

            if i == 0:
                chosen = -1
                for x in range(26):
                    diff = ci - x
                    if diff < 0:
                        diff = -diff
                    if diff + dp[(i + 1) * M + x * 3] == remaining:
                        chosen = x
                        break

                if chosen == -1:
                    return ""

                cost = ci - chosen if ci >= chosen else chosen - ci
                res.append(chr(chosen + 97))
                remaining -= cost
                prev_c = chosen
                prev_l = 1

            else:
                chosen = -1

                if prev_l < 3:
                    chosen = prev_c
                    cost = ci - chosen if ci >= chosen else chosen - ci
                else:
                    for x in range(26):
                        if x == prev_c:
                            new_l = 3
                        else:
                            new_l = 1

                        diff = ci - x
                        if diff < 0:
                            diff = -diff

                        if diff + dp[(i + 1) * M + x * 3 + (new_l - 1)] == remaining:
                            chosen = x
                            cost = diff
                            break

                    if chosen == -1:
                        return ""

                res.append(chr(chosen + 97))
                remaining -= cost

                if chosen == prev_c:
                    if prev_l < 3:
                        prev_l += 1
                else:
                    prev_c = chosen
                    prev_l = 1

        return ''.join(res)
