from typing import List

class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        L = 4 * side
        t = []
        for x, y in points:
            if y == 0:
                t.append(x)
            elif x == side:
                t.append(side + y)
            elif y == side:
                t.append(3 * side - x)
            else:  # x == 0
                t.append(4 * side - y)

        t.sort()
        n = len(t)

        def feasible(D: int) -> bool:
            if D == 0:
                return True
            if k * D > L:
                return False

            t2 = t + [v + L for v in t]
            m = 2 * n
            nxt = [m] * m

            j = 0
            for i in range(m):
                if j <= i:
                    j = i + 1
                target = t2[i] + D
                while j < m and t2[j] < target:
                    j += 1
                nxt[i] = j

            for i in range(n):
                idx = i
                ok = True

                for _ in range(k - 1):
                    idx = nxt[idx]
                    if idx >= i + n:
                        ok = False
                        break

                if ok and t2[i] + L - t2[idx] >= D:
                    return True

            return False

        lo, hi = 0, side
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if feasible(mid):
                lo = mid
            else:
                hi = mid - 1

        return lo
