from array import array

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n = len(grid)
        m = len(grid[0])
        N = n * m

        dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]
        next_val = [2, 2, 0]

        cont = []
        for d in range(4):
            dr, dc = dirs[d]
            arr = array('H', [0]) * N
            rows = range(n - 1, -1, -1) if dr == 1 else range(n)

            for r in rows:
                base = r * m
                for c in range(m):
                    idx = base + c
                    v = grid[r][c]
                    nr = r + dr
                    nc = c + dc

                    if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == next_val[v]:
                        arr[idx] = 1 + arr[nr * m + nc]
                    else:
                        arr[idx] = 1

            cont.append(arr)

        ans = 0

        for d in range(4):
            dr, dc = dirs[d]
            end = array('H', [0]) * N
            rows = range(n) if dr == 1 else range(n - 1, -1, -1)

            for r in rows:
                base = r * m
                for c in range(m):
                    idx = base + c
                    v = grid[r][c]
                    L = 0

                    if v == 1:
                        L = 1
                    else:
                        pr = r - dr
                        pc = c - dc
                        if 0 <= pr < n and 0 <= pc < m:
                            pidx = pr * m + pc
                            pv = grid[pr][pc]

                            if v == 2:
                                if pv != 2 and end[pidx] > 0:
                                    L = end[pidx] + 1
                            elif v == 0:
                                if pv == 2 and end[pidx] > 0:
                                    L = end[pidx] + 1

                    end[idx] = L

                    if L > ans:
                        ans = L

                    if L > 0:
                        nd = (d + 1) % 4
                        total = L + cont[nd][idx] - 1
                        if total > ans:
                            ans = total

        return ans
