class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        L = n + m - 1
        ans = ['?'] * L

        # Apply all forced 'T' constraints first.
        for i, c in enumerate(str1):
            if c == 'T':
                for j in range(m):
                    pos = i + j
                    if ans[pos] != '?' and ans[pos] != str2[j]:
                        return ""
                    ans[pos] = str2[j]

        # Process 'F' constraints from left to right.
        for i, c in enumerate(str1):
            if c == 'F':
                # Check whether this window would equal str2 if all remaining '?' become 'a'.
                potential_equal = True
                for j in range(m):
                    pos = i + j
                    if ans[pos] == '?':
                        if str2[j] != 'a':
                            potential_equal = False
                            break
                    else:
                        if ans[pos] != str2[j]:
                            potential_equal = False
                            break

                # If it would equal str2, we must break the equality.
                if potential_equal:
                    change_pos = -1
                    for j in range(m - 1, -1, -1):
                        pos = i + j
                        if ans[pos] == '?':
                            change_pos = pos
                            break

                    # No '?' available to change: impossible.
                    if change_pos == -1:
                        return ""

                    ans[change_pos] = 'b'

        # Fill remaining unknown positions with the smallest letter.
        for i in range(L):
            if ans[i] == '?':
                ans[i] = 'a'

        return ''.join(ans)
