class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        L = n + m - 1

        word = ['a'] * L
        forced = [False] * L

        # Apply all 'T' constraints first
        for i, ch in enumerate(str1):
            if ch == 'T':
                for j in range(m):
                    pos = i + j
                    c = str2[j]
                    if forced[pos]:
                        if word[pos] != c:
                            return ""
                    else:
                        forced[pos] = True
                        word[pos] = c

        modified = [False] * L

        # Process 'F' constraints from left to right
        for i, ch in enumerate(str1):
            if ch == 'F':
                # Check if the current window equals str2
                equal = True
                for j in range(m):
                    if word[i + j] != str2[j]:
                        equal = False
                        break

                if equal:
                    # Find the rightmost position in this window that can still be changed
                    found = -1
                    for j in range(i + m - 1, i - 1, -1):
                        if not forced[j] and not modified[j]:
                            found = j
                            break

                    if found == -1:
                        return ""

                    # Change it to the smallest character that differs from str2 at this offset
                    offset = found - i
                    if str2[offset] != 'a':
                        word[found] = 'a'
                    else:
                        word[found] = 'b'
                    modified[found] = True

        return ''.join(word)
