class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)
        prev1 = [[1] * (k + 1) for _ in range(n)]
        prev2 = None

        for length in range(2, n + 1):
            m = n - length + 1
            cur = [[0] * (k + 1) for _ in range(m)]

            for i in range(m):
                j = i + length - 1
                d = abs(ord(s[i]) - ord(s[j]))
                cost = min(d, 26 - d)

                left = prev1[i]
                right = prev1[i + 1]
                arr = cur[i]

                if length == 2:
                    for c in range(k + 1):
                        best = left[c] if left[c] > right[c] else right[c]
                        if c >= cost and 2 > best:
                            best = 2
                        arr[c] = best
                else:
                    inner = prev2[i + 1]
                    for c in range(k + 1):
                        best = left[c] if left[c] > right[c] else right[c]
                        if c >= cost:
                            cand = inner[c - cost] + 2
                            if cand > best:
                                best = cand
                        arr[c] = best

            prev2 = prev1
            prev1 = cur

        return prev1[0][k]
