class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)

        dist = [[0] * 26 for _ in range(26)]
        for a in range(26):
            for b in range(a, 26):
                d = min(b - a, 26 - (b - a))
                dist[a][b] = dist[b][a] = d

        dp = [[None] * n for _ in range(n)]

        for i in range(n):
            dp[i][i] = bytearray([1]) * (k + 1)

        for length in range(2, n + 1):
            for i in range(n - length + 1):
                j = i + length - 1
                left = dp[i + 1][j]
                right = dp[i][j - 1]
                d = dist[ord(s[i]) - 97][ord(s[j]) - 97]
                arr = bytearray(k + 1)

                if length == 2:
                    for c in range(k + 1):
                        val = left[c] if left[c] > right[c] else right[c]
                        if c >= d and 2 > val:
                            val = 2
                        arr[c] = val
                else:
                    inner = dp[i + 1][j - 1]
                    for c in range(k + 1):
                        val = left[c] if left[c] > right[c] else right[c]
                        if c >= d:
                            cand = 2 + inner[c - d]
                            if cand > val:
                                val = cand
                        arr[c] = val

                dp[i][j] = arr

        return dp[0][n - 1][k]
