class Solution:
    def distanceSum(self, m: int, n: int, k: int) -> int:
        MOD = 10**9 + 7
        N = m * n

        fact = [1] * (N + 1)
        for i in range(1, N + 1):
            fact[i] = fact[i - 1] * i % MOD

        invfact = [1] * (N + 1)
        invfact[N] = pow(fact[N], MOD - 2, MOD)
        for i in range(N, 0, -1):
            invfact[i - 1] = invfact[i] * i % MOD

        comb = fact[N - 2] * invfact[k - 2] % MOD * invfact[N - k] % MOD

        def sum_diffs(length: int) -> int:
            if length <= 1:
                return 0
            return (length * (length - 1) * (length + 1) // 6) % MOD

        total_pair_distance = (
            (n * n % MOD) * sum_diffs(m) +
            (m * m % MOD) * sum_diffs(n)
        ) % MOD

        return comb * total_pair_distance % MOD
