from typing import List

class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)
        if k > n - 1:
            return [0] * n

        children = [{}]
        cnt = [0]
        depth = [0]
        terminal = [0] * n

        for idx, s in enumerate(words):
            node = 0
            for ch in s:
                nxt = children[node].get(ch)
                if nxt is None:
                    nxt = len(children)
                    children[node][ch] = nxt
                    children.append({})
                    cnt.append(0)
                    depth.append(depth[node] + 1)
                node = nxt
                cnt[node] += 1
            terminal[idx] = node

        cnt[0] = n
        M = len(children)

        tin = [0] * M
        tout = [0] * M
        anc_good = [0] * M

        timer = 0
        stack = [(0, 0, 0)]
        while stack:
            node, state, pm = stack.pop()
            if state == 0:
                tin[node] = timer
                timer += 1

                d = depth[node]
                if cnt[node] >= k + 1 and d > pm:
                    pm = d
                anc_good[node] = pm

                stack.append((node, 1, 0))
                for child in children[node].values():
                    stack.append((child, 0, pm))
            else:
                tout[node] = timer - 1

        pref = [0] * (M + 1)
        suff = [0] * (M + 1)

        for u in range(M):
            if cnt[u] >= k:
                d = depth[u]
                r = tout[u] + 1
                if d > pref[r]:
                    pref[r] = d

                l = tin[u]
                if d > suff[l]:
                    suff[l] = d

        for i in range(1, M + 1):
            if pref[i - 1] > pref[i]:
                pref[i] = pref[i - 1]

        for i in range(M - 1, -1, -1):
            if suff[i + 1] > suff[i]:
                suff[i] = suff[i + 1]

        ans = [0] * n
        for i, t in enumerate(terminal):
            p = tin[t]
            best = pref[p]
            if suff[p + 1] > best:
                best = suff[p + 1]
            if anc_good[t] > best:
                best = anc_good[t]
            ans[i] = best

        return ans
