class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        n = numberOfUsers
        ans = [0] * n
        online = [True] * n
        offline_until = [0] * n

        sorted_events = sorted(events, key=lambda e: int(e[1]))
        i = 0
        m = len(sorted_events)

        while i < m:
            t = int(sorted_events[i][1])

            # Automatic online returns happen before any event at time t.
            for u in range(n):
                if not online[u] and offline_until[u] <= t:
                    online[u] = True
                    offline_until[u] = 0

            # Process all OFFLINE events at time t before any MESSAGE events.
            j = i
            while j < m and int(sorted_events[j][1]) == t:
                if sorted_events[j][0] == "OFFLINE":
                    u = int(sorted_events[j][2])
                    online[u] = False
                    offline_until[u] = t + 60
                j += 1

            # Process all MESSAGE events at time t.
            j = i
            while j < m and int(sorted_events[j][1]) == t:
                if sorted_events[j][0] == "MESSAGE":
                    mentions = sorted_events[j][2]
                    for token in mentions.split():
                        if token == "ALL":
                            for u in range(n):
                                ans[u] += 1
                        elif token == "HERE":
                            for u in range(n):
                                if online[u]:
                                    ans[u] += 1
                        else:
                            u = int(token[2:])
                            ans[u] += 1
                j += 1

            i = j

        return ans
