class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        L = n + m - 1

        # KMP prefix function for str2
        pi = [0] * m
        for i in range(1, m):
            j = pi[i - 1]
            while j > 0 and str2[i] != str2[j]:
                j = pi[j - 1]
            if str2[i] == str2[j]:
                j += 1
            pi[i] = j

        # KMP transitions for states 0..m
        trans = [[0] * 26 for _ in range(m + 1)]
        for s in range(m + 1):
            for c in range(26):
                ch = chr(ord('a') + c)
                if s == m:
                    k = pi[m - 1]
                else:
                    k = s

                while k > 0 and str2[k] != ch:
                    k = pi[k - 1]
                if str2[k] == ch:
                    k += 1
                trans[s][c] = k

        # reach[s] is a bitmask of all states reachable from s by one character
        reach = [0] * (m + 1)
        for s in range(m + 1):
            mask = 0
            for c in range(26):
                mask |= 1 << trans[s][c]
            reach[s] = mask

        all_mask = (1 << (m + 1)) - 1
        bits = [1 << i for i in range(m + 1)]

        # dp[pos] is a bitmask of states from which positions pos..L-1 can be completed
        dp = [0] * (L + 1)
        dp[L] = all_mask

        for pos in range(L - 1, -1, -1):
            if pos < m - 1:
                allowed = all_mask
            else:
                i = pos - (m - 1)
                if str1[i] == 'T':
                    allowed = bits[m]
                else:
                    allowed = all_mask ^ bits[m]

            target = allowed & dp[pos + 1]
            if target == 0:
                dp[pos] = 0
                continue

            cur = 0
            for s in range(m + 1):
                if reach[s] & target:
                    cur |= bits[s]
            dp[pos] = cur

        if not (dp[0] & bits[0]):
            return ""

        # Reconstruct lexicographically smallest string
        res = []
        state = 0
        for pos in range(L):
            if pos < m - 1:
                allowed = all_mask
            else:
                i = pos - (m - 1)
                if str1[i] == 'T':
                    allowed = bits[m]
                else:
                    allowed = all_mask ^ bits[m]

            for c in range(26):
                ns = trans[state][c]
                if (allowed & bits[ns]) and (dp[pos + 1] & bits[ns]):
                    res.append(chr(ord('a') + c))
                    state = ns
                    break

        return ''.join(res)
