class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        s = side
        t = []
        for x, y in points:
            if y == 0:
                t.append(x)
            elif x == s:
                t.append(s + y)
            elif y == s:
                t.append(2 * s + (s - x))
            else:
                t.append(3 * s + (s - y))
        t.sort()
        n = len(t)
        L = 4 * s

        def feasible(d: int) -> bool:
            if d == 0:
                return n >= k

            arr = t + [v + L for v in t]
            m = 2 * n
            nxt = [m] * m
            j = 0
            for i in range(m):
                if j <= i:
                    j = i + 1
                while j < m and arr[j] < arr[i] + d:
                    j += 1
                nxt[i] = j

            for i in range(n):
                curr = i
                ok = True
                for _ in range(k - 1):
                    curr = nxt[curr]
                    if curr >= m:
                        ok = False
                        break
                if not ok:
                    continue
                if arr[curr] - arr[i] <= L - d:
                    return True
            return False

        lo, hi = 0, s
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if feasible(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo
