                    cnt1 = 1
                elif x == max1:
                    cnt1 += 1
                    if x > max2:
                        max2 = x
                else:
                    if x > max2:
                        max2 = x

            union_invalid += max1

            if cnt1 == 1 and max1 > 0:
                exclusive[max1_id] += max1 - max2

        total = n * (n + 1) // 2
        return total - union_invalid + max(exclusive)
