            if a > b:
                a, b = b, a
            by_a[a].append((b, idx))

        INF = n + 1
        cnt = [0] * (n + 2)
        first_id = [-1] * (n + 2)

        min1 = INF
        min2 = INF

        base = 0
        gain = [0] * m

        for l in range(n, 0, -1):
            for b, idx in by_a[l]:
                if cnt[b] == 0:
                    first_id[b] = idx
                    if b < min1:
                        min2 = min1
                        min1 = b
                    elif b < min2:
                        min2 = b
                cnt[b] += 1

            if min1 == INF:
                base += INF - l
            else:
                base += min1 - l
                if cnt[min1] == 1:
                    second = min2 if min2 != INF else INF
                    gain[first_id[min1]] += second - min1

        return base + max(gain)
```

```python
from typing import List

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n = len(grid)
        m = len(grid[0])

        # Directions in clockwise order:
        # SE, SW, NW, NE
        dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]

        # f[d][i][j] = longest valid straight segment starting at (i, j)
        # moving in direction d, including (i, j).
        f = [[[1] * m for _ in range(n)] for _ in range(4)]

        for d, (dr, dc) in enumerate(dirs):
            fd = f[d]
            if dr == 1:
                rows = range(n - 1, -1, -1)
            else:
                rows = range(n)

            for i in rows:
                row = grid[i]
                for j in range(m):
                    ni = i + dr
                    nj = j + dc
                    if 0 <= ni < n and 0 <= nj < m:
                        v = row[j]
                        expected = 0 if v == 2 else 2
                        if grid[ni][nj] == expected:
                            fd[i][j] = 1 + fd[ni][nj]

        ans = 0

        # Compute longest valid incoming segment ending at each cell for each direction,
        # and combine it with a clockwise turn.
        for d, (dr, dc) in enumerate(dirs):
            pref = [[0] * m for _ in range(n)]

            if dr == 1:
                rows = range(n)
            else:
                rows = range(n - 1, -1, -1)

            d2 = (d + 1) & 3
            f2 = f[d2]

            for i in rows:
                grow = grid[i]
                prow = pref[i]
                for j in range(m):
                    if grow[j] == 1:
                        cur = 1
                    else:
                        pi = i - dr
                        pj = j - dc
                        if 0 <= pi < n and 0 <= pj < m:
                            prev = pref[pi][pj]
                            if prev > 0:
                                vp = grid[pi][pj]
                                expected = 0 if vp == 2 else 2
                                if grow[j] == expected:
                                    cur = prev + 1
                                else:
                                    cur = 0
                            else:
                                cur = 0
                        else:
                            cur = 0

                    prow[j] = cur

                    if cur > ans:
                        ans = cur

                    if cur > 0:
                        val = cur + f2[i][j] - 1
                        if val > ans:
                            ans = val

        return ans
